import { Injectable, signal, WritableSignal } from '@angular/core';

export type ToastType = 'success' | 'error' | 'warning';

export interface ToastState {
  message: string;
  type: ToastType;
  visible: boolean;
}

@Injectable({ providedIn: 'root' })
export class ToastService {
  public toast: WritableSignal<ToastState | null> = signal(null);

  private showTimer?: ReturnType<typeof setTimeout>;
  private removeTimer?: ReturnType<typeof setTimeout>;

  private clearTimers() {
    if (this.showTimer) {
      clearTimeout(this.showTimer);
      this.showTimer = undefined;
    }
    if (this.removeTimer) {
      clearTimeout(this.removeTimer);
      this.removeTimer = undefined;
    }
  }

  private scheduleHide() {
    this.clearTimers();
    // After 4s start exit animation, then remove after animation completes
    this.showTimer = setTimeout(() => {
      const current = this.toast();
      if (current) {
        this.toast.set({ ...current, visible: false });
        this.removeTimer = setTimeout(() => this.toast.set(null), 260);
      }
      this.showTimer = undefined;
    }, 4000);
  }

  private show(message: string, type: ToastType) {
    this.clearTimers();
    this.toast.set({ message, type, visible: true });
    this.scheduleHide();
  }

  success(message: string) {
    this.show(message, 'success');
  }

  error(message: string) {
    this.show(message, 'error');
  }

  warning(message: string) {
    this.show(message, 'warning');
  }

  close() {
    this.clearTimers();
    // Play exit animation then clear
    const current = this.toast();
    if (current) {
      this.toast.set({ ...current, visible: false });
      this.removeTimer = setTimeout(() => this.toast.set(null), 260);
    }
  }
}

import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ToastService } from '../../services/toast.service';

@Component({
  selector: 'app-toast',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './toast.component.html',
  styleUrls: ['./toast.component.scss'],
})
export class ToastComponent {
  private toastService = inject(ToastService);
  readonly toast = this.toastService.toast;

  close() {
    this.toastService.close();
  }
}

:host {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 9999;
  pointer-events: none;
}

.toast-portal {
  display: flex;
  justify-content: center;
  padding: calc(var(--space-md, 16px));
  pointer-events: none;
}

.toast {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: calc(var(--space-md, 12px));
  background: var(--color-surface, #fff);
  color: var(--color-on-surface, #222);
  border-radius: var(--radius-md, 12px);
  box-shadow: var(--shadow-md, 0 10px 30px rgba(0,0,0,0.12));
  padding: calc(var(--space-md, 12px));
  max-width: min(92%, 640px);
  width: auto;
  transform: translateY(12px);
  opacity: 0;
  transition: transform 240ms cubic-bezier(.22,.9,.23,1), opacity 200ms ease;
  align-items: center;
}

.toast.visible {
  transform: translateY(0);
  opacity: 1;
}

.icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  font-size: calc(var(--font-size-sm, 14px) + 4px);
  flex: 0 0 32px;
}

.message {
  flex: 1 1 auto;
  font-size: var(--font-size-sm, 14px);
  line-height: 1.2;
}

.close {
  background: transparent;
  border: 0;
  color: inherit;
  font-size: 18px;
  cursor: pointer;
  padding: 6px;
  line-height: 1;
}

.toast.success {
  border-left: 6px solid var(--toast-success, #2a7a2a);
}

.toast.success .icon {
  background: color-mix(in srgb, var(--toast-success, #2a7a2a) 12%, transparent);
  color: var(--toast-success, #2a7a2a);
}

.toast.error {
  border-left: 6px solid var(--toast-error, #b00020);
}

.toast.error .icon {
  background: color-mix(in srgb, var(--toast-error, #b00020) 12%, transparent);
  color: var(--toast-error, #b00020);
}

.toast.warning {
  border-left: 6px solid var(--toast-warning, #b36b00);
}

.toast.warning .icon {
  background: color-mix(in srgb, var(--toast-warning, #b36b00) 12%, transparent);
  color: var(--toast-warning, #b36b00);
}

import { Component, signal, ViewChild, ElementRef } from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { RouterLink, RouterLinkActive } from '@angular/router';
import { ToastComponent } from './shared/toast/toast.component';

@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink, RouterLinkActive, ToastComponent],
  templateUrl: './app.html',
  styleUrl: './app.scss'
})
export class App {
  protected readonly title = signal('angular-app');

  @ViewChild('menuToggle') menuToggle!: ElementRef<HTMLInputElement>;

  closeMenu() {
    if (this.menuToggle) {
      this.menuToggle.nativeElement.checked = false;
    }
  }
}

