import { Component, Input, Output, EventEmitter } from '@angular/core';
import { NgFor, NgClass, NgIf } from '@angular/common';
import { RecipeDetail } from '../recipe-detail/recipe-detail';
import { Recipe } from '../../models/index';

@Component({
  selector: 'app-recipe-list',
  standalone: true,
  imports: [NgFor, NgClass, NgIf, RecipeDetail],
  templateUrl: './recipe-list.html',
  styleUrl: './recipe-list.scss',
})
export class RecipeList {
  @Input() recipes: Recipe[] = [];
  @Output() edit = new EventEmitter<Recipe>();

  selectedRecipe: Recipe | null = null;

  openRecipe(recipe: Recipe) {
    this.selectedRecipe = recipe;
  }

  closeRecipe() {
    this.selectedRecipe = null;
  }
}

import { Component } from '@angular/core';
import { RecipeList } from './recipe-list/recipe-list';
import { SearchBar } from './search-bar/search-bar';
import { EmptyState } from './empty-state/empty-state';
import { NgIf } from '@angular/common';
import { NgForOf } from '@angular/common';
import { Recipe } from '../models/recipe';
import { RecipeEditor } from './recipe-editor/recipe-editor';
import { SkeletonCard } from './skeleton-card/skeleton-card';
import { RecipeService } from '../services/recipe.service';

const recipeImage = 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=600&q=80';

@Component({
  selector: 'app-recipe-catalog',
  standalone: true,
  imports: [RecipeList, SearchBar, EmptyState, NgIf, NgForOf, RecipeEditor, SkeletonCard],
  templateUrl: './recipe-catalog.html',
  styleUrl: './recipe-catalog.scss',
})
export class RecipeCatalog {
  showEditor = false;
  editingRecipe: Recipe | null = null;

  constructor(public recipeService: RecipeService) {}

  // Cast to `any[]` to avoid template type-checking issues caused by
  // duplicate `LegacyRecipe` symbols between modules during ngtypecheck.
  get recipes(): Recipe[] {
    return this.recipeService.recipes() as Recipe[];
  }

  get filteredRecipes(): Recipe[] {
    return this.recipeService.filteredRecipes() as Recipe[];
  }
  openEditor(recipe?: Recipe) {
    this.editingRecipe = recipe ?? null;
    this.showEditor = true;
  }

  closeEditor() {
    this.showEditor = false;
    this.editingRecipe = null;
  }

  async onEditorSave(recipe: Recipe) {
    if (this.editingRecipe && this.editingRecipe.id) {
      // Edit flow — use pessimistic update
      const updated = await this.recipeService.updateRecipe(this.editingRecipe.id, recipe as Partial<Recipe>);
      if (updated) this.closeEditor();
    } else {
      const added = await this.recipeService.addRecipe(recipe);
      if (added) this.closeEditor();
    }
  }
}

import { Component, Output, EventEmitter, Input } from '@angular/core';
import { NgIf, NgFor } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Recipe } from '../../models/recipe';
import { ALL_CATEGORIES, CATEGORY_ID_MAP, RecipeCategory } from '../../models/categories';

@Component({
  selector: 'app-recipe-editor',
  standalone: true,
  imports: [NgIf, NgFor, ReactiveFormsModule],
  templateUrl: './recipe-editor.html',
  styleUrl: './recipe-editor.scss',
})
export class RecipeEditor {
  @Output() close = new EventEmitter<void>();
  @Output() save = new EventEmitter<Recipe>();
  @Input() initialRecipe?: Recipe | null;

  form: FormGroup;
  categories = ALL_CATEGORIES;


  constructor(private fb: FormBuilder) {
    this.form = this.fb.group({
      title: ['', Validators.required],
      description: ['', Validators.required],
      imageUrl: [''],
      category: [''],
      difficulty: ['könnyű'],
      prepTime: [30],
      calories: [0],
      servings: [1],
      ingredientsText: [''], // newline separated ingredient lines: "name|amount|unit"
      stepsText: [''], // newline separated steps
      protein: [0],
      carbs: [0],
      fat: [0],
      isPublic: [true]
    });
    // If initialRecipe is provided after creation, it will be set via the Input setter below (Angular will call property assignment before change detection)
  }

  ngOnChanges() {
    this.applyInitial();
  }

  private applyInitial() {
    const r = this.initialRecipe as any;
    if (!r) {
      this.form.reset({
        title: '', description: '', imageUrl: '', category: '', difficulty: 'könnyű', prepTime: 30,
        calories: 0, servings: 1, ingredientsText: '', stepsText: '', protein: 0, carbs: 0, fat: 0, isPublic: true
      });
      return;
    }

    // Map categoryId back to category label if possible
    let categoryLabel = '';
    for (const [label, id] of Object.entries(CATEGORY_ID_MAP)) {
      if (id === r.categoryId) { categoryLabel = label; break; }
    }

    const ingredientsText = (r.ingredients || []).map((ing: any) => `${ing.ingredientName || ''}|${ing.amount || 0}|${ing.unit || ''}`).join('\n');
    const stepsText = (r.steps || []).join('\n');

    this.form.patchValue({
      title: r.title || '',
      description: r.description || '',
      imageUrl: r.imageUrl || r.image || '',
      category: categoryLabel,
      difficulty: r.difficulty || 'könnyű',
      prepTime: r.prepTime || 0,
      calories: r.calories || 0,
      servings: r.servings || 1,
      ingredientsText,
      stepsText,
      protein: r.nutrition?.protein || 0,
      carbs: r.nutrition?.carbs || 0,
      fat: r.nutrition?.fat || 0,
      isPublic: !!r.isPublic
    });
  }



  saveRecipe() {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const v = this.form.value;

    const ingredients = (v.ingredientsText || '').split('\n').map((line: string) => line.trim()).filter((l: string) => !!l).map((l: string, idx: number) => {
      const parts = l.split('|').map((p: string) => p.trim());
      return {
        ingredientId: `ing_${Date.now()}_${idx}`,
        ingredientName: parts[0] || 'ingredient',
        amount: Number(parts[1] || 0),
        unit: parts[2] || ''
      };
    });

    const steps = (v.stepsText || '').split('\n').map((s: string) => s.trim()).filter((s: string) => !!s);

    const now = new Date().toISOString();
    const categoryId = v.category ? (CATEGORY_ID_MAP[v.category] || null) : null;

    const id = (this.initialRecipe && this.initialRecipe.id) ? this.initialRecipe.id : `recipe_${Date.now()}`;

    const recipe: Recipe = {
      id,
      title: v.title,
      description: v.description,
      imageUrl: v.imageUrl || undefined,
      categoryId: categoryId || undefined,
      difficulty: v.difficulty || 'könnyű',
      prepTime: Number(v.prepTime) || 0,
      calories: Number(v.calories) || 0,
      servings: Number(v.servings) || 1,
      diet: [],
      nutrition: {
        protein: Number(v.protein) || 0,
        carbs: Number(v.carbs) || 0,
        fat: Number(v.fat) || 0
      },
      ingredients: ingredients,
      steps: steps,
      ownerId: 'user_demo',
      isPublic: !!v.isPublic,
      createdAt: (this.initialRecipe && this.initialRecipe.createdAt) ? this.initialRecipe.createdAt : now,
      updatedAt: now
    };

    this.save.emit(recipe);
  }
}

import { Component, Input, Output, EventEmitter } from '@angular/core';
import { NgIf, CommonModule } from '@angular/common';
import { Recipe } from '../../models/index';
import { RecipeService } from '../../services/recipe.service';

@Component({
  selector: 'app-recipe-detail',
  standalone: true,
  imports: [CommonModule, NgIf],
  templateUrl: './recipe-detail.html',
  styleUrl: './recipe-detail.scss',
})
export class RecipeDetail {
  @Input() recipe!: Recipe;
  @Output() close = new EventEmitter<void>();
  @Output() edit = new EventEmitter<Recipe>();
  constructor(private recipeService: RecipeService) {}

  async confirmDelete() {
    if (!this.recipe || !this.recipe.id) return;

    const usages = await this.recipeService.checkRecipeUsage(this.recipe.id);
    let msg = 'Biztosan törlöd a receptet?';
    if (usages.length) {
      msg = `Ez a recept ${usages.length} heti menüben szerepel (hetek: ${usages.join(', ')}). Biztosan törlöd?`;
    }

    if (window.confirm(msg)) {
      const ok = await this.recipeService.deleteRecipe(this.recipe.id);
      if (ok) this.close.emit();
    }
  }

  onEdit() {
    if (this.recipe) this.edit.emit(this.recipe);
  }
}

