      const payload: any = {
        weekOf: menu.weekStart,
        userId: menu.userId || 'unknown',
        items: items,
        generatedAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      };
      if (weeklyIdToSave) payload.weeklyMenuId = weeklyIdToSave;

      let listId: string | null = null;
      if (snap && !snap.empty) {
        // existing -> ask to overwrite
        const docSnap = snap.docs[0];
