          return;
        }
        await setDoc(doc(db, 'shopping-list', docSnap.id), payload);
        listId = docSnap.id;
      } else {
        const docRef = await addDoc(col, payload);
        listId = docRef.id;
      }

      const now = new Date().toISOString();
      const saved: ShoppingList = {
        id: listId as string,
        weekOf: menu.weekStart,
        userId: menu.userId || 'unknown',
        weeklyMenuId: weeklyIdToSave,
        items,
        generatedAt: now,
        updatedAt: now,
      };

      this._currentList.set(saved);
      this.toast.success(`Bevásárlólista elkészült! (${items.length} tétel)`);
    } catch (err) {
      console.error('generateList error:', err);
      this.toast.error('Hiba a lista generálásánál');
    }
  }

  clearList(): void {
    this._currentList.update(list => {
