        const docSnap = snap.docs[0];
        const confirmed = window.confirm('Van már bevásárlólista ehhez a héthez. Felülírod?');
        if (!confirmed) {
          this.toast.error('A meglévő lista megőrzésre került.');
          return;
        }
        await setDoc(doc(db, 'shopping-list', docSnap.id), payload);
        listId = docSnap.id;
      } else {
        const docRef = await addDoc(col, payload);
        listId = docRef.id;
      }

      const now = new Date().toISOString();
      const saved: ShoppingList = {
        id: listId as string,
        weekOf: menu.weekStart,
        userId: menu.userId || 'unknown',
        weeklyMenuId: weeklyIdToSave,
        items,
        generatedAt: now,
