            id: `item_${Date.now()}_${Math.random().toString(36).slice(2,8)}`,
            ingredientId: e.ingredientId,
            ingredientName: e.ingredientName,
            totalAmount: Number(parseFloat(String(e.amount)).toFixed(3)),
            unit: e.unit || '',
            categoryId: catId,
            categoryName: catName,
            checked: false,
            isManual: false,
            fromRecipeIds: Array.from(e.fromRecipeIds),
          });
        }
      }

      // 6) group by category done by existing computed signals when rendering — persist as-is

      // 7) save to Firestore (collection: shopping-list)
      const col = collection(db, 'shopping-list');
      // see if exists by weeklyMenuId or by weekOf
      let snap: any = null;
      if (weeklyMenuId) {
        const q1 = query(col, where('weeklyMenuId', '==', weeklyMenuId));
        snap = await getDocs(q1);
      } else if (menu && menu.weekStart) {
        const q2 = query(col, where('weekOf', '==', menu.weekStart));
        snap = await getDocs(q2);
      }

      const weeklyIdToSave = weeklyMenuId ?? (menu && (menu as any).id ? (menu as any).id : undefined);
      const payload: any = {
        weekOf: menu.weekStart,
        userId: menu.userId || 'unknown',
        items: items,
        generatedAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      };
      if (weeklyIdToSave) payload.weeklyMenuId = weeklyIdToSave;

      let listId: string | null = null;
      if (snap && !snap.empty) {
        // existing -> overwrite without confirmation
        const docSnap = snap.docs[0];
        await setDoc(doc(db, 'shopping-list', docSnap.id), payload);
        listId = docSnap.id;
      } else {
        const docRef = await addDoc(col, payload);
        listId = docRef.id;
      }

      const now = new Date().toISOString();
      const saved: ShoppingList = {
        id: listId as string,
        weekOf: menu.weekStart,
        userId: menu.userId || 'unknown',
        weeklyMenuId: weeklyIdToSave,
        items,
        generatedAt: now,
        updatedAt: now,
      };

      this._currentList.set(saved);
      this.toast.success(`Bevásárlólista elkészült! (${items.length} tétel)`);
    } catch (err) {
      console.error('generateList error:', err);
      this.toast.error('Hiba a lista generálásánál');
    }
