            if (e.unit === conv.unit) {
              e.amount += conv.amount;
              e.fromRecipeIds.add(rid);
              merged = true;
              break;
            }
          }
          if (!merged) {
            const newE: TmpEntry = { ingredientId: iid ?? undefined, ingredientName: iname, amount: conv.amount, unit: conv.unit, fromRecipeIds: new Set([rid]) };
            entries.push(newE);
            byIngredient.set(key, entries);
          }
        }
      }

      // 5) enrich with ingredient/category info
      const ingredientsList: any[] = await firstValueFrom(this.http.get<any[]>('/assets/data/ingredients.json')).catch(() => [] as any[]);
      const categoriesList: any[] = await firstValueFrom(this.http.get<any[]>('/assets/data/categories.json')).catch(() => [] as any[]);
      const ingredientMap = new Map<string, any>();
      for (const ii of ingredientsList) ingredientMap.set(ii.id, ii);
      const categoryMap = new Map<string, any>();
      for (const c of categoriesList) categoryMap.set(c.id, c);

      const items: ShoppingItem[] = [];
      for (const [key, entries] of byIngredient.entries()) {
        for (const e of entries) {
          // determine category
          let catId: string | undefined = undefined;
          let catName: string | undefined = undefined;
          if (e.ingredientId && ingredientMap.has(e.ingredientId)) {
            const ii = ingredientMap.get(e.ingredientId);
            catId = ii.categoryId;
            if (catId && categoryMap.has(catId)) catName = categoryMap.get(catId).name;
          }

          items.push({
            id: `item_${Date.now()}_${Math.random().toString(36).slice(2,8)}`,
            ingredientId: e.ingredientId,
            ingredientName: e.ingredientName,
            totalAmount: Number(parseFloat(String(e.amount)).toFixed(3)),
            unit: e.unit || '',
            categoryId: catId,
            categoryName: catName,
            checked: false,
            isManual: false,
            fromRecipeIds: Array.from(e.fromRecipeIds),
          });
        }
      }

      // 6) group by category done by existing computed signals when rendering — persist as-is

      // 7) save to Firestore (collection: shopping-list)
      const col = collection(db, 'shopping-list');
      // see if exists by weeklyMenuId or by weekOf
      let snap: any = null;
      if (weeklyMenuId) {
        const q1 = query(col, where('weeklyMenuId', '==', weeklyMenuId));
        snap = await getDocs(q1);
      } else if (menu && menu.weekStart) {
        const q2 = query(col, where('weekOf', '==', menu.weekStart));
        snap = await getDocs(q2);
      }

      const weeklyIdToSave = weeklyMenuId ?? (menu && (menu as any).id ? (menu as any).id : undefined);
      const payload: any = {
        weekOf: menu.weekStart,
        userId: menu.userId || 'unknown',
        items: items,
        generatedAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      };
      if (weeklyIdToSave) payload.weeklyMenuId = weeklyIdToSave;

      let listId: string | null = null;
      if (snap && !snap.empty) {
        // existing -> overwrite without confirmation
        const docSnap = snap.docs[0];
        await setDoc(doc(db, 'shopping-list', docSnap.id), payload);
        listId = docSnap.id;
      } else {
        const docRef = await addDoc(col, payload);
        listId = docRef.id;
      }

      const now = new Date().toISOString();
      const saved: ShoppingList = {
        id: listId as string,
        weekOf: menu.weekStart,
        userId: menu.userId || 'unknown',
        weeklyMenuId: weeklyIdToSave,
        items,
        generatedAt: now,
        updatedAt: now,
      };

      this._currentList.set(saved);
      this.toast.success(`Bevásárlólista elkészült! (${items.length} tétel)`);
    } catch (err) {
      console.error('generateList error:', err);
      this.toast.error('Hiba a lista generálásánál');
    }
  }

  clearList(): void {
    this._currentList.update(list => {
      if (!list) return list;
      return { ...list, items: [], updatedAt: new Date().toISOString() };
    });
  }

  onItemToggled(itemId: string) {
    this._currentList.update(list => {
      if (!list) return list;
      const items = list.items.map(it => (it.id === itemId ? { ...it, checked: !it.checked } : it));
      const updated = { ...list, items, updatedAt: new Date().toISOString() };
      void this._persistCurrentList();
      return updated;
    });
  }

  onItemDeleted(itemId: string) {
    this._currentList.update(list => {
      if (!list) return list;
      const items = list.items.filter(it => it.id !== itemId);
      const updated = { ...list, items, updatedAt: new Date().toISOString() };
      void this._persistCurrentList();
      return updated;
    });
  }

  onItemAdded(payload: Partial<ShoppingItem>) {
    const newItem: ShoppingItem = {
      id: payload.id ?? `item_${Date.now()}`,
      ingredientId: payload.ingredientId,
      ingredientName: payload.ingredientName ?? payload.ingredientId ?? 'Új tétel',
      totalAmount: payload.totalAmount ?? 1,
      unit: payload.unit ?? Unit.Piece,
      categoryId: payload.categoryId,
      categoryName: payload.categoryName,
      checked: payload.checked ?? false,
      isManual: payload.isManual ?? false,
      fromRecipeIds: payload.fromRecipeIds ?? [],
    };
    this._currentList.update(list => {
      if (!list) return list;
      const updated = { ...list, items: [...list.items, newItem], updatedAt: new Date().toISOString() };
      void this._persistCurrentList();
      return updated;
    });
  }

  private async _persistCurrentList(): Promise<void> {
    try {
      const list = this._currentList();
      if (!list) return;

      const col = collection(db, 'shopping-list');

      // Prefer to find an existing Firestore doc by weeklyMenuId or weekOf
      let existingSnap: any = null;
      if (list.weeklyMenuId) {
        const q1 = query(col, where('weeklyMenuId', '==', list.weeklyMenuId));
        existingSnap = await getDocs(q1);
      } else if (list.weekOf) {
        const q2 = query(col, where('weekOf', '==', list.weekOf));
        existingSnap = await getDocs(q2);
      }

      const payload: any = {
        weekOf: list.weekOf,
        userId: list.userId || 'unknown',
        items: list.items,
        generatedAt: list.generatedAt || new Date().toISOString(),
        updatedAt: serverTimestamp(),
      };
      if (list.weeklyMenuId) payload.weeklyMenuId = list.weeklyMenuId;

      let savedId: string | null = null;
      if (existingSnap && !existingSnap.empty) {
        const docSnap = existingSnap.docs[0];
        await setDoc(doc(db, 'shopping-list', docSnap.id), payload);
        savedId = docSnap.id;
      } else if (list.id) {
        // Try to update by id if present (may create a doc with that id)
        try {
          const ref = doc(db, 'shopping-list', list.id);
          const docCheck = await getDoc(ref);
          if (docCheck.exists()) {
            await setDoc(ref, payload);
            savedId = list.id;
          } else {
            const docRef = await addDoc(col, payload);
            savedId = docRef.id;
          }
        } catch (err) {
          const docRef = await addDoc(col, payload);
          savedId = docRef.id;
        }
      } else {
        const docRef = await addDoc(col, payload);
        savedId = docRef.id;
      }

      if (savedId) {
        const now = new Date().toISOString();
        this._currentList.update(l => l ? { ...l, id: savedId, updatedAt: now, generatedAt: l.generatedAt || now } : l);
      }
    } catch (err) {
      console.error('Failed to persist shopping list:', err);
      this.toast.error('A bevásárlólista mentése sikertelen volt.');
    }
  }

  copyText(): void {
    const text = this.toPlainText();
    if (navigator.clipboard) navigator.clipboard.writeText(text);
  }

  toPlainText(): string {
    const list = this._currentList();
    if (!list || !list.items.length) return '';
    const groups = new Map<string, ShoppingItem[]>();
    for (const it of list.items) {
      const k = it.categoryName ?? 'Egyéb';
      groups.set(k, [...(groups.get(k) ?? []), it]);
    }
    let out: string[] = [];
    for (const [title, items] of groups) {
      out.push(`${title}`);
      out.push(...items.map(i => `- ${i.ingredientName} ${i.totalAmount ?? ''}${i.unit ? ' ' + i.unit : ''}`));
      out.push('');
    }
    return out.join('\n').trim();
  }

  print(): void {
    window.print();
  }

  resetAll(): void {
    this._currentList.set(null);
  }
}

export default ShoppingService;

