          })[0] ?? null;
        } else {
          list = res;
        }

        if (list) {
          this._currentList.set(list);
          this.filterNonPurchasable();
        }
      },
      error: (err) => {
        console.error('Failed to load shopping list from assets:', err);
      }
    });
  }

  filterNonPurchasable() {
